#![no_main]
zkaleido_sp1_guest_env::entrypoint!(main);

use alpen_params::AlpenSpecId;
use strata_predicate::{PredicateKey, PredicateTypeId};
use alpen_proof_acct::process_ee_acct_update;
use zkaleido_sp1_guest_env::Sp1ZkVmEnv;

/// Compile-time-baked build artifact generated by `build.rs`: the chunk
/// guest's Groth16 predicate condition bytes. Not zkVM input — see
/// `alpen_proof_acct::process_ee_acct_update` for why.
mod predicates {
    include!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../generated/predicates.rs"
    ));
}

/// Constructs the chunk proof predicate key from the Groth16 predicate
/// condition bytes that `build.rs` embeds in `predicates.rs`.
fn chunk_predicate_key() -> PredicateKey {
    PredicateKey::try_new(
        PredicateTypeId::Sp1Groth16,
        predicates::ALPEN_CHUNK_PREDICATE_CONDITION_BYTES.to_vec(),
    )
    .expect("embedded Groth16 condition fits within the key length limit")
}

/// The spec version this guest proves under. Hardcoded, not read from zkVM
/// input: it is what binds the version into this program's verifying key, so
/// a prover cannot pick which rules its update is checked under. One guest
/// package per version.
const SPEC_VERSION: AlpenSpecId = AlpenSpecId::V1;

fn main() {
    let key = chunk_predicate_key();
    process_ee_acct_update(&Sp1ZkVmEnv, SPEC_VERSION, &key)
}
